-- State transitions declared for Branch (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION organization.branches_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'inactive'), ('inactive', 'active'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: branches.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS branches_status_transition_check ON organization.branches;
CREATE TRIGGER branches_status_transition_check
    BEFORE UPDATE OF "status" ON organization.branches
    FOR EACH ROW EXECUTE FUNCTION organization.branches_status_transition_check();
